7: // Returns the user's access consent status as a string.
8: Napi::Value GetAuthStatus(const Napi::CallbackInfo &info) {
9:   Napi::Env env = info.Env();
10:   std::string auth_status;
11: 
12:   const std::string type = info[0].As<Napi::String>().Utf8Value();
13:   if (type == "contacts") {
14:     auth_status = ContactAuthStatus();
15:   } else if (type == "calendar") {
16:     auth_status = EventAuthStatus("calendar");
17:   } else if (type == "reminders") {
18:     auth_status = EventAuthStatus("reminders");
19:   } else if (type == "full-disk-access") {
20:     auth_status = FDAAuthStatus();
21:   } else if (type == "microphone") {
22:     auth_status = MediaAuthStatus("microphone");
23:   } else if (type == "photos-add-only") {
24:     auth_status = PhotosAuthStatus("add-only");
25:   } else if (type == "photos-read-write") {
26:     auth_status = PhotosAuthStatus("read-write");
27:   } else if (type == "speech-recognition") {
28:     auth_status = SpeechRecognitionAuthStatus();
29:   } else if (type == "camera") {
30:     auth_status = MediaAuthStatus("camera");
31:   } else if (type == "accessibility") {
32:     auth_status = AXIsProcessTrusted() ? kAuthorized : kDenied;
33:   } else if (type == "location") {
34:     auth_status = LocationAuthStatus();
35:   } else if (type == "screen") {
36:     auth_status = ScreenAuthStatus();
37:   } else if (type == "bluetooth") {
38:     auth_status = BluetoothAuthStatus();
39:   } else if (type == "music-library") {
40:     auth_status = MusicLibraryAuthStatus();
41:   } else if (type == "input-monitoring") {
42:     auth_status = InputMonitoringAuthStatus();
43:   }
44: 
45:   return Napi::Value::From(env, auth_status);
46: }
