48: // Request access to various protected folders on the system.
49: Napi::Promise AskForFoldersAccess(const Napi::CallbackInfo &info) {
50:   Napi::Env env = info.Env();
51:   Napi::Promise::Deferred deferred = Napi::Promise::Deferred::New(env);
52:   const std::string folder_name = info[0].As<Napi::String>().Utf8Value();
53: 
54:   NSString *path = @"";
55:   if (folder_name == "documents") {
56:     NSURL *url = URLForDirectory(NSDocumentDirectory);
57:     path = [url path];
58:   } else if (folder_name == "downloads") {
59:     NSURL *url = URLForDirectory(NSDownloadsDirectory);
60:     path = [url path];
61:   } else if (folder_name == "desktop") {
62:     NSURL *url = URLForDirectory(NSDesktopDirectory);
63:     path = [url path];
64:   }
65: 
66:   NSError *error = nil;
67:   NSFileManager *fm = [NSFileManager defaultManager];
68:   NSArray<NSString *> *contents __unused =
69:       [fm contentsOfDirectoryAtPath:path error:&error];
70: 
71:   std::string status = (error) ? kDenied : kAuthorized;
72:   deferred.Resolve(Napi::String::New(env, status));
73:   return deferred.Promise();
74: }
