77: Napi::Promise AskForContactsAccess(const Napi::CallbackInfo &info) {
78:   Napi::Env env = info.Env();
79:   Napi::Promise::Deferred deferred = Napi::Promise::Deferred::New(env);
80:   Napi::ThreadSafeFunction ts_fn = Napi::ThreadSafeFunction::New(
81:       env, Napi::Function::New(env, NoOp), "contactsCallback", 0, 1);
82: 
83:   __block Napi::ThreadSafeFunction tsfn = ts_fn;
84:   CNContactStore *store = [CNContactStore new];
85:   [store
86:       requestAccessForEntityType:CNEntityTypeContacts
87:                completionHandler:^(BOOL granted, NSError *error) {
88:                  auto callback = [=](Napi::Env env, Napi::Function js_cb,
89:                                      const char *granted) {
90:                    deferred.Resolve(Napi::String::New(env, granted));
91:                  };
92:                  tsfn.BlockingCall(granted ? "authorized" : "denied", callback);
93:                  tsfn.Release();
94:                }];
95: 
96:   return deferred.Promise();
97: }
