153:   Napi::Env env = info.Env();
154:   Napi::Promise::Deferred deferred = Napi::Promise::Deferred::New(env);
155:   Napi::ThreadSafeFunction ts_fn = Napi::ThreadSafeFunction::New(
156:       env, Napi::Function::New(env, NoOp), "cameraCallback", 0, 1);
