167:                                         const char *granted) {
168:                       deferred.Resolve(Napi::String::New(env, granted));
169:                     };
170: 
171:                     tsfn.BlockingCall(granted ? "authorized" : "denied",
172:                                       callback);
173:                     tsfn.Release();
